// Wrap an angle to [-PI, PI] SAFELY. The old inline `while(a>PI)a-=2PI` loops
// spin forever if `a` is +/-Inf (Inf minus a finite value is still Inf), which
// froze the game when an aim/heading angle went non-finite. fmodf is bounded and
// a non-finite input collapses to 0 so a corrupted angle can never lock a frame.
static inline float ex_wrap_pi(float a) {
  if (!isfinite(a)) return 0.0f;
  a = fmodf(a + 3.14159265f, 6.28318531f);
  if (a < 0.0f) a += 6.28318531f;
  return a - 3.14159265f;
}

