// HIT CONFIRM: every real chunk of damage the player lands answers with a tight tick
// (rate-limited; per-frame DoT crumbs are filtered) -- "am I damaging it", answered.
// KILLSTREAKS: kills inside a rolling 3.5s window chain into callouts. The counter
// lives here (before the message globals) and the announcement is emitted later
// in the frame where the HUD strings are in scope.
static float g_anim_t;                  // tentative decl (real def below)
static int   g_streak_n = 0;
static float g_streak_last = -100.0f;
static int   g_streak_announce = 0;
static void hitstop(float strength);
static float g_hitmark; static int g_hitmark_kill;   // fwd (defined with the game-feel state below)
static int enemy_damage_fx(ex_enemy_t *en, float d){
  int fresh_tick = (d >= 1.0f && g_tick_cd <= 0.0f && g_sfx_tick);
  int r = ex_enemy_damage(en, d);
  if (fresh_tick){ sfx(g_sfx_tick); g_tick_cd = 0.07f; }
  if (r){
    hitstop(0.7f);   // a KILL crunches time -- the satisfying beat that says "it died"
    g_hitmark = 0.22f; g_hitmark_kill = 1;   // kill marker: brighter, longer
    if (g_anim_t - g_streak_last < 3.5f) g_streak_n++; else g_streak_n = 1;
    g_streak_last = (float)g_anim_t;
    if (g_streak_n >= 2) g_streak_announce = g_streak_n;
  } else if (d >= 8.0f && fresh_tick){
    hitstop(0.12f); // a solid non-killing hit: a tiny bump of weight, throttled with the tick
    if (g_hitmark <= 0.0f || !g_hitmark_kill){ g_hitmark = 0.12f; g_hitmark_kill = 0; }  // hit confirm (don't override a kill mark)
  }
  return r;
}
