static int mfont_mask(char c){
  switch (c){
    case 'A': return 247;  case 'B': return 4751; case 'C': return 57;   case 'D': return 4623;
    case 'E': return 249;  case 'F': return 241;  case 'G': return 189;  case 'H': return 246;
    case 'I': return 4617; case 'K': return 9328; case 'L': return 56;   case 'M': return 1334;
    case 'N': return 8502; case 'O': return 63;   case 'P': return 243;  case 'R': return 8435;
    case 'S': return 237;  case 'T': return 4609; case 'U': return 62;   case 'V': return 3120;
    case 'W': return 10294;case 'X': return 11520;case 'Y': return 5376; case 'Z': return 3081;
    default:  return 0;
  }
}
