static float g_morph_dir = 0.0f;  // set non-zero to drive it   // per-part limb angle, so children can compose from parents  // tire roll + fan spin accumulators
// ARMOR REACTION: armor/shin-guard parts shift when the body is hit or when the
// suspension takes a hard hit (crater/bump). Jolt spikes on impact then springs
// back, so panels visibly absorb the blow instead of riding rigid.
static float g_armor_jolt = 0.0f, g_armor_jolt_v = 0.0f;   // impulse + velocity (spring)
static float g_armor_dir[2] = {0,0};                        // world-space hit direction
// auto-orientation suggested defaults (auto_orient.py analysis of the 48 models):
// 34/48 come in lying/rotated; these seed the harness so they start upright.
// ~70% right (up-axis reliable, vehicle/robot ~70%); all overridable in-game (F4).
// env-scale set-pieces (very flat/huge) render bigger than character slot allows
// UI LOG: a ring buffer of recent events/changes, shown on-screen (toggle key D).
// Every tuning change + notable event is appended here so it can be read back
// instead of eyeballing the HUD. Also mirrored to stdout.
#define EX_LOG_LINES 14
#define EX_LOG_LEN   72
static char  g_log[EX_LOG_LINES][EX_LOG_LEN];
static int   g_log_head = 0;      // next write slot
static int   g_log_count = 0;     // how many valid lines
static int   g_log_show = 0;      // D toggles the log panel
static int   g_sandbox = 0;       // sandbox mode: no enemies, free tuning
static void game_log(const char *fmt, ...) {
  va_list ap; va_start(ap, fmt);
  vsnprintf(g_log[g_log_head], EX_LOG_LEN, fmt, ap);
  va_end(ap);
  printf("[log] %s\n", g_log[g_log_head]);          // also to stdout
  g_log_head = (g_log_head + 1) % EX_LOG_LINES;
  if (g_log_count < EX_LOG_LINES) g_log_count++;
}
