    case EX_ELEM_FIRE:     c[0]=255;c[1]=120;c[2]=40;  break;
    case EX_ELEM_AIR:      c[0]=220;c[1]=240;c[2]=220; break;
    case EX_ELEM_ELECTRIC: c[0]=255;c[1]=240;c[2]=120; break;
    case EX_ELEM_VINE:     c[0]=120;c[1]=220;c[2]=120; break;
