// STRUCTURAL SKELETON: a dedicated pool for DESIGNED bones + armour, placed
// deterministically per frame archetype -- the part of a build's identity the random
// greebles never gave. 0..11 sphere joints, 12..29 rib slats, 30..35 armour plates
// (2 pauldrons + 2 knee + 2 elbow guards), 36..39 SPINAL COLUMN segments, 40..47 HOLLOW
// LIMB STRUT-FRAMES (paired rails -- robotic, hollow, cybertronian), 48..49 angled CHEST
// PANELS, 50..51 HIP RING plates, 52..53 SHIN FINS, 54..55 ANIMATED EYES, 56 JAW BAR,
// 57..58 BROW PLATES (the face rig, driven by a micro-FSM + LOD), 59..65 DEPTH PLATES
// (inset secondary panels on chest/abdomen/head/pauldrons/thighs), 66..73 SEGMENTED LIMB
// BANDS (forearm + shin armour wraps with gaps), 74..75 KNUCKLE GUARDS, 76..77 TOE CAPS,
// 78..79 ANKLE PISTONS (compress on landing), 80..81 BACK BOOST-STACKS (heat-glow with
// thrust), 82..83 FOREARM INSET PANELS (dark machined recesses), 84..85 HEAD ANTENNAE
// -- layered thickness, not flat faces. (The same parts you'd hand-craft in
// tools/part_editor.html, composed here from the pool.)
#define SKEL_MODELS 92
static ex_model_t   *g_skel_models[SKEL_MODELS];
// map alt_mode -> a frame archetype: 0 agile/beast, 1 heavy/siege, 2 flyer, 3 balanced.
static int frame_archetype(int alt){
  switch(alt){
    case 0: case 11: case 6: case 7: case 5: case 12: case 15: return 0;
    case 1: case 9: case 16: case 19: return 1;
    case 2: case 8: case 14: case 17: case 18: return 2;
    default: return 3;
  }
}
// place one structural box/sphere at a body-local offset+size, inheriting the body's
// yaw + gait lean exactly like the base parts (so it rides the silhouette in motion).
// bend a limb bone about its TOP joint by `th` radians, keeping the joint attached (pivot
// compensation on the bone's center); the bone's tip child (foot/hand) follows the swing.
static void limb_bend(ex_part_pose_t *poses, float *ppitch, int part, int tip, float th){
  float pv = poses[part].sy;
  poses[part].offset[1] += pv*(1.0f - cosf(th));
  poses[part].offset[2] -= pv*sinf(th);
  ppitch[part] += th * 57.2957795f;
  if (tip >= 0){ float len = poses[part].sy*2.0f;
    poses[tip].offset[1] += len*(1.0f - cosf(th));
    poses[tip].offset[2] -= len*sinf(th);
  }
}
static void skel_place(ex_model_t *m, float ex_, float ey, float ez,
                       float lox, float loy, float loz, float sx, float sy, float sz,
                       float cy, float syw, float ydeg, float lean_s, float lean_f, const uint8_t *col){
  if (!m) return;
  float gh = loy>0?loy:0; float ox=lox+gh*lean_s, oz=loz+gh*lean_f;
  m->position[0]=ex_+ox*cy-oz*syw; m->position[1]=ey+loy; m->position[2]=ez+ox*syw+oz*cy;
  m->rotation[0]=0; m->rotation[1]=ydeg; m->rotation[2]=0;
  m->scale3[0]=fabsf(cy)*sx+fabsf(syw)*sz; m->scale3[1]=sy; m->scale3[2]=fabsf(cy)*sz+fabsf(syw)*sx;
  if (m->scale3[0]<0.02f && m->scale3[1]<0.02f && m->scale3[2]<0.02f){ m->position[1]=-100000.0f; return; }
  if (m->scale3[0]<0.02f) m->scale3[0]=0.02f; if (m->scale3[1]<0.02f) m->scale3[1]=0.02f; if (m->scale3[2]<0.02f) m->scale3[2]=0.02f;
  m->tint[0]=col[0]/255.0f; m->tint[1]=col[1]/255.0f; m->tint[2]=col[2]/255.0f; m->is_lit=1; m->emissive_solid=0;
}
