// CLING: full surface attachment -- sideways on walls, inverted under ceilings. JUMP is
// GRIP: hold it near a face to latch; move keys traverse the face plane; release to drop.
// SAFETY is a grip meter: vertical faces drain slow, UNDERSIDES drain fast, heavier
// builds drain faster, crawler alt-modes (spider/insect/scorpion/crab) grip far better,
// and ice is slick. Empty grip = you fall.
