static int   g_vent_lock   = 0;      // redlined: the gun VENTS until heat falls to 0.35
static float g_cam_trauma = 0.0f;    // camera shake energy (0..1), decays
static float g_hitstop = 0.0f;       // impact freeze timer (real seconds); scales gameplay dt while active
static float g_hitstop_scale = 0.0f; // how far time is squeezed during the current hitstop (0=frozen)
static float g_hitmark = 0.0f;       // hit-marker flash timer: crosshair confirms a landed shot
static int   g_hitmark_kill = 0;     // this marker was a KILL (drawn brighter/differently)
// Request an impact freeze. strength 0..1: light chip ~0.03s barely-slowed,
// a kill ~0.09s near-frozen. The strongest active request wins so a kill's
// crunch always reads over a chip hit that lands the same frame.
static void hitstop(float strength){
  if (strength < 0.0f) strength = 0.0f; if (strength > 1.0f) strength = 1.0f;
  float dur = 0.025f + strength * 0.075f;      // 0.025s .. 0.10s
  float squeeze = 0.35f - strength * 0.35f;    // light hits slow to 0.35x, kills to ~0
  if (dur > g_hitstop){ g_hitstop = dur; g_hitstop_scale = squeeze; }
}
