// nearest collider FACE within reach: returns box index, outward normal, glue point
static int player_nearest_face(const float *pp, float reach, float *out_n, float *out_p){
  int best=-1; float bd=reach*reach;
  for (int c2=0; c2<g_map_col_n; c2++){ const float *B=g_map_col[c2];
    if (B[4] < 1.6f) continue;                                  // too squat to cling
    float qx=fmaxf(B[0]-B[3], fminf(pp[0], B[0]+B[3]));
    float qy=fmaxf(B[1]-B[4], fminf(pp[1], B[1]+B[4]));
    float qz=fmaxf(B[2]-B[5], fminf(pp[2], B[2]+B[5]));
    float ddx=pp[0]-qx, ddy=pp[1]-qy, ddz=pp[2]-qz;
    float dd=ddx*ddx+ddy*ddy+ddz*ddz;
    if (dd < bd && dd > 1e-6f){ bd=dd; best=c2;
      float ax=fabsf(ddx), ay=fabsf(ddy), az=fabsf(ddz);
      out_n[0]=out_n[1]=out_n[2]=0.0f;
      if (ax>=ay && ax>=az) out_n[0]=(ddx>0)?1.0f:-1.0f;
      else if (ay>=az)      out_n[1]=(ddy>0)?1.0f:-1.0f;
      else                  out_n[2]=(ddz>0)?1.0f:-1.0f;
      out_p[0]=qx; out_p[1]=qy; out_p[2]=qz;
    }
  }
  return best;
}

