    if (ex_keys_down[SDL_SCANCODE_RIGHTBRACKET]){ g_imported_idx=(g_imported_idx+1)%EX_N_IMPORTED; ex_keys_down[SDL_SCANCODE_RIGHTBRACKET]=0; game_log("model > %s", g_imported_names[g_imported_idx]); }
