    int dbg_active=0; for(int i=0;i<NUM_DEBRIS;i++) if(g_debris[i].active) dbg_active++;
    float spd=sqrtf(e->velocity[0]*e->velocity[0]+e->velocity[2]*e->velocity[2]);
