    // arrow toward the hit source, relative to facing
    float rel = atan2f(g_hit_dir[2]-e->position[2], g_hit_dir[0]-e->position[0]) - atan2f(camera->front[2],camera->front[0]);
    const char *arw = "^"; float d=rel;
